def transform(grid):
    from collections import Counter
    # Find background color (most common value)
    all_values = []
    for row in grid:
        all_values.extend(row)
    background = Counter(all_values).most_common(1)[0][0]

    result = []
    for row in grid:
        # Convert all background values to 1 if any non-background exists in this row
        has_non_bg = any(cell != background for cell in row)
        if has_non_bg:
            new_row = []
            for cell in row:
                if cell == background:
                    new_row.append(1)
                else:
                    new_row.append(cell)
            result.append(new_row)
        else:
            # All background, keep unchanged
            result.append(row)
    return result
